INSERT INTO categories (id, parent_id, name, slug, description, image_url, sort_order, is_active)
VALUES
(1, NULL, 'Classic Jhola Shoulder Bag', 'classic-jhola-shoulder-bag', 'Handcrafted on traditional pit looms. Perfect for Daily Errands, college, and Office.', 'https://images.dailyobjects.com/marche/product-images/1204/space-blue-idyll-tote-images/Space-Blue-Idyll-Tote.png?tr=cm-pad_resize,v-3', 1, 1),
(2, NULL, 'Cross-Body Sling Bag', 'cross-body-sling-bag', 'Hands-free sling bags and crossbody carry for outings and travel.', 'https://images.dailyobjects.com/marche/product-images/1811/pivot-crossbody-sand-images/Pivot-Crossbody-Sand.png?tr=cm-pad_resize,v-3', 2, 1),
(3, NULL, 'Everyday Tote Bag', 'everyday-tote-bag', 'Signature heavyweight cotton canvas tote. Perfect for Work, shopping, beach, and books.', 'https://images.dailyobjects.com/marche/product-images/1204/pivot-classic-tote-basalt-images/do-Pivot-Classic-Tote-Basalt.png?tr=cm-pad_resize,v-3', 3, 1),
(4, NULL, 'Market/Shopping Bag', 'market-shopping-bag', 'Eco-friendly, reusable shopping bag. Perfect for Replacing Plastic carry bags.', 'https://images.dailyobjects.com/marche/product-images/1204/ivory-crimson-red-field-tote-bag-images/Ivory-Crimson-Red-Field-Tote-Bag-vw.png?tr=cm-pad_resize,v-3', 4, 1),
(5, NULL, 'Potli Bag', 'potli-bag', 'Artisanal festive potli bag with heritage motifs. Perfect for Weddings, Festivals, and Gifting.', 'https://images.dailyobjects.com/marche/product-images/1811/red-puft-bucket-sling-bag-images/Red-Puft-Buckets-Slings-Bagss.png?tr=cm-pad_resize,v-3', 5, 1),
(6, NULL, 'Laptop Sleeve', 'laptop-sleeve', 'Padded protective sleeve. Padded Protection for 13-15'''' laptops.', 'https://images.dailyobjects.com/marche/product-images/1202/pivot-meridian-convertible-briefpack-sand-images/Pivot-Meridian-Convertible-Briefpack-Sand.png?tr=cm-pad_resize,v-3', 6, 1),
(7, NULL, 'Zip Pouch / Utility Pouch', 'zip-pouch-utility-pouch', 'Compact multipurpose zip organizer. Perfect for Cables, stationery, and essentials.', 'https://images.dailyobjects.com/marche/product-images/1301/carbon-black-easy-square-pouch-images/Carbon-Black-Easy-Square-Pouch.png?tr=cm-pad_resize,v-3', 7, 1),
(8, NULL, 'Cosmetic / Makeup Pouch', 'cosmetic-makeup-pouch', 'Structured vanity cosmetic pouch. Perfect for Travel and vanity organizing.', 'https://images.dailyobjects.com/marche/product-images/1301/dailyobjects-crimson-red-regular-taxi-organiser-images/DailyObjects-Crimson-Red-Regular-Taxi-Organiser-Medium.png?tr=cm-pad_resize,v-3', 8, 1),
(9, NULL, 'Coin Purse & Wallet Pouch', 'coin-purse-wallet-pouch', 'Palm-sized handcrafted wallet pouch. Perfect for Small change, cards, and keys.', 'https://images.dailyobjects.com/marche/product-images/1703/dailyobjects-navy-blue-tiny-taxi-organiser-images/DailyObjects-Navy-Blue-Tiny-Taxi-Organiser-Small-4.png?tr=cm-pad_resize,v-3', 9, 1),
(10, NULL, 'Tiffin / Lunch Bag', 'tiffin-lunch-bag', 'Box-bottom insulated lunch bag. Insulated-style carry for lunch boxes.', 'https://images.dailyobjects.com/marche/product-images/1204/dailyobjects-midnight-blue-buoy-tote-bag-images/DailyObjects-Midnight-Blue-Buoyant-Tote-Bag.png?tr=cm-pad_resize,v-3', 10, 1),
(11, NULL, 'Passport & Travel Pouch', 'passport-travel-pouch', 'Slim, secure travel organizer. Perfect for Documents, tickets, and forex.', 'https://images.dailyobjects.com/marche/product-images/1811/pivot-travel-sling-sand-images/Pivot-Travel-Sling-Sand-vw.png?tr=cm-pad_resize,v-3', 11, 1),
(12, NULL, 'Mobile Pouch', 'mobile-pouch', 'Minimalist crossbody phone pouch. Perfect for Phone and earphones on the go.', 'https://images.dailyobjects.com/marche/product-images/1811/monkey-shoulder-x-do-utility-phone-sling-images/Monkey-Shoulder-x-DO-Black-Utility-Phone-Sling.png?tr=cm-pad_resize,v-3', 12, 1)
