)
VALUES
(1, 1, 'Classic Pitloom Jhola Bag', 'classic-pitloom-jhola-bag', 'Handcrafted on traditional pit looms by Bethany artisans in Bapatla. Crafted from 100% pure yarn-dyed cotton with ergonomic wide shoulder strap and natural breathable weave.', 'Perfect for Daily Errands, college, and Office.', 'BL-JHL-001', 999.00, 1499.00, 33.36, 45, 'BESTSELLER', 1, 1, 4.70, 25, 1),
